import { mkdirSync, writeFileSync } from "node:fs";

// Deterministic entry image for 23 November 2026 world news.
// The PNG bytes below are written unchanged on every run.
const data = "";

mkdirSync("output", { recursive: true });
writeFileSync("output/entry.png", Buffer.from(data, "base64"));
console.log("Wrote output/entry.png");
